struct Resource { int value; };

// Safe initialization
std::shared_ptr<Resource> p1 =
    std::make_shared<Resource>(Resource{42});

// Shared ownership established (Copy constructor)
std::shared_ptr<Resource> p2 = p1;

// Access the managed object
p2->value = 100;

// Check reference count (Count == 2)
long count = p1.use_count();

// Release ownership of p1
p1.reset();

// Check reference count (Count == 1)
count = p2.use_count();

// Get raw pointer (Use with caution!)
Resource* raw = p2.get();

// Object is destroyed when p2 is released.
